<?php
defined('ABSPATH') || exit;

/** Opt-in private future conversations. No commerce tool output, credentials or model-weight training. */
final class AISA_Conversations {
 const TYPE='aisa_conversation'; const CONFIG='aisa_conversation_config'; const LOCK='aisa_conversation_lock'; const CLEAN='aisa_conversation_cleanup'; const TTL=7*DAY_IN_SECONDS; const LIMIT=100; const TURNS=20; const BYTES=65536;
 public static function schedule_cleanup(){if(!wp_next_scheduled(self::CLEAN)&&self::posts(array('posts_per_page'=>1)))wp_schedule_single_event(time()+60,self::CLEAN);}
 public static function boot(){add_action('init',array(__CLASS__,'types'));add_action('init',array(__CLASS__,'schedule_cleanup')); add_action('admin_post_aisa_conversation',array(__CLASS__,'handle'));add_action(self::CLEAN,array(__CLASS__,'cleanup'));add_action('delete_user',array(__CLASS__,'delete_user'),4,1);add_filter('wp_privacy_personal_data_exporters',function($v){$v['aisa-conversations']=array('exporter_friendly_name'=>'AI support conversations','callback'=>array(__CLASS__,'export_personal'));return $v;});add_filter('wp_privacy_personal_data_erasers',function($v){$v['aisa-conversations']=array('eraser_friendly_name'=>'AI support conversations','callback'=>array(__CLASS__,'erase_personal'));return $v;});}
 public static function types(){ $caps=array_fill_keys(array('edit_post','read_post','delete_post','edit_posts','edit_others_posts','publish_posts','read_private_posts','create_posts','delete_posts','delete_others_posts','edit_private_posts','edit_published_posts','delete_private_posts','delete_published_posts'),'do_not_allow'); register_post_type(self::TYPE,array('public'=>false,'publicly_queryable'=>false,'show_ui'=>false,'show_in_rest'=>false,'can_export'=>false,'delete_with_user'=>true,'supports'=>array(),'capabilities'=>$caps)); }
 public static function config(){ $v=get_option(self::CONFIG);return is_array($v)&&array_keys($v)===array('enabled','auto_review','actor')&&in_array($v['enabled'],array(0,1),true)&&in_array($v['auto_review'],array(0,1),true)&&is_int($v['actor'])?$v:array('enabled'=>0,'auto_review'=>0,'actor'=>0); }
 public static function config_revision(){return hash('sha256',wp_json_encode(self::config()));}
 public static function guard(){if(!current_user_can('manage_options')||get_current_user_id()<1)wp_die('Not allowed.','',array('response'=>403));check_admin_referer('aisa_conversation');}
 public static function redacted($text,$limit=4000){
  if(!is_string($text)||strlen($text)>12000||!preg_match('//u',$text)||strpos($text,"\0")!==false)return '[Unsupported text omitted]';
  // Skip sensitive turns completely; masking alone cannot make private order/credential content learning material.
  if(preg_match('~(?:password|passwd|api[ _-]?key|access[ _-]?token|secret|otp|one.time.code|order[ _-]?(?:id|number|key|#)|download_file|wc_order_|pay_for_order|प[ा]?सवर्ड|ओटीपी|ऑर्डर\s*(?:नंबर|नम्बर|#)|-----BEGIN[^\r\n]*PRIVATE KEY)~iu',$text)||preg_match('~\b(?:nvapi-|sk-[A-Za-z]|AIza)[A-Za-z0-9_-]{8,}~',$text))return '[Private support detail omitted]';
  $text=preg_replace(array('~https?://[^\s<>]+~iu','~[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}~iu','~\+?\d[\d\s().-]{7,}\d~u','~\b[A-Za-z0-9_+/=-]{40,}\b~'), '[redacted]', $text);
  $text=sanitize_textarea_field($text);return strlen($text)<=$limit?$text:'[Long support detail omitted]';
 }
 private static function posts($args=array()){return get_posts(array_merge(array('post_type'=>self::TYPE,'post_status'=>array_merge(array('private'),array_values(get_post_stati())),'posts_per_page'=>self::LIMIT+1,'orderby'=>'ID','order'=>'ASC','suppress_filters'=>true),$args));}
 public static function state($p){
  if(!$p||$p->post_type!==self::TYPE||!in_array($p->post_status,array('private','trash'),true)||strlen($p->post_content)>self::BYTES)return false;$s=json_decode($p->post_content,true,12);
  if(!is_array($s)||!in_array(array_keys($s),array(array('site','owner','key','created','updated','expires','revision','reviewed','messages'),array('site','owner','key','created','updated','expires','revision','reviewed','messages','desk')),true)||$s['site']!==get_current_blog_id()||$s['owner']!==(int)$p->post_author||(string)get_post_meta($p->ID,'aisa_conversation_owner',true)!==(string)$s['owner']||!is_string($s['key'])||!preg_match('/^[a-f0-9]{64}$/D',$s['key'])||get_post_meta($p->ID,'aisa_conversation_key',true)!==$s['key']||!is_array($s['messages'])||count($s['messages'])>self::TURNS)return false;
  foreach(array('created','updated','expires','revision')as$k)if(!is_int($s[$k])||$s[$k]<1)return false;
  if($s['updated']<$s['created']||$s['expires']>$s['created']+self::TTL||$s['owner']<0||($s['owner']&&!get_userdata($s['owner']))||!in_array($s['reviewed'],array(0,1),true))return false;
  if(isset($s['desk'])){if(!AISA_Live_Inbox::valid($s['desk'])||$s['desk']['read']>count($s['messages']))return false;$pending=$s['desk']['pending'];if($pending>=0&&($s['desk']['mode']!=='ai'||!isset($s['messages'][$pending])||$s['messages'][$pending]['outcome']!=='pending'))return false;}
  foreach($s['messages']as$m)if(!is_array($m)||array_keys($m)!==array('at','question','answer','outcome')||!is_int($m['at'])||!is_string($m['question'])||!is_string($m['answer'])||strlen($m['question'])>4000||strlen($m['answer'])>6000||!in_array($m['outcome'],array('answer','error','pending','human'),true))return false;return $s;
 }
 public static function record($r,$question,$answer,$outcome='answer'){
  if(!self::config()['enabled']||$r->get_param('archive_consent')!==true||is_wp_error(AISA_Memory::validate($r->get_param('scope'))))return false;
  $session=$r->get_param('session');if(!is_string($session)||!preg_match('/^[a-f0-9]{32}$/D',$session)||!in_array($outcome,array('answer','error','pending','human'),true))return false;
  if(!add_option(self::LOCK,time(),'','no'))return false;
  try{
   if(!self::prune())return false;$key=hash_hmac('sha256',AISA_Memory::scope().'|'.$session,wp_salt('nonce'));$rows=self::posts(array('meta_key'=>'aisa_conversation_key','meta_value'=>$key));$p=$rows?$rows[0]:null;$s=$p?self::state($p):false;$now=time();
   if($p&&(!$s||$p->post_status!=='private'||$s['expires']<=$now||$s['owner']!==get_current_user_id()))return false;
   if(!$p&&count(self::posts())>=self::LIMIT)return false;
   if(!$s)$s=array('site'=>get_current_blog_id(),'owner'=>get_current_user_id(),'key'=>$key,'created'=>$now,'updated'=>$now,'expires'=>$now+self::TTL,'revision'=>0,'reviewed'=>0,'messages'=>array());
   if(count($s['messages'])>=self::TURNS)return false;$s['messages'][]=array('at'=>$now,'question'=>self::redacted($question),'answer'=>self::redacted($answer,6000),'outcome'=>$outcome);$s['updated']=$now;$s['revision']++;$s['reviewed']=0;$json=wp_json_encode($s);if(strlen($json)>self::BYTES)return false;
   $data=array('post_type'=>self::TYPE,'post_status'=>'private','post_author'=>get_current_user_id(),'post_title'=>'Support conversation','post_content'=>$json);if($p)$data['ID']=$p->ID;else$data['meta_input']=array('aisa_conversation_key'=>$key,'aisa_conversation_owner'=>(string)get_current_user_id());
   $id=wp_insert_post(wp_slash($data),true);if(!$id||is_wp_error($id))return false;if(self::state(get_post($id))!==$s){if(!$p)wp_delete_post($id,true);return false;}if(!wp_next_scheduled(self::CLEAN))wp_schedule_single_event(time()+HOUR_IN_SECONDS,self::CLEAN);return true;
  }finally{delete_option(self::LOCK);}
 }
 private static function purge($post){
  // A reviewed public FAQ is independent knowledge; unapproved copied drafts remain private conversation data.
  foreach(get_posts(array('post_type'=>'aisa_knowledge','post_status'=>'private','posts_per_page'=>100,'meta_key'=>'aisa_conversation_id','meta_value'=>(int)$post->ID,'suppress_filters'=>true))as$draft){$origin=AISA_Training::origin($draft);if(($origin['kind']??'')==='conversation'&&(int)($origin['conversation']??0)===(int)$post->ID&&!AISA_Agent::knowledge_approved($draft)){if(!wp_delete_post($draft->ID,true)||get_post($draft->ID)!==null)return false;}}
  // Fail closed if more linked pending data exists beyond a single bounded cleanup batch.
  $remaining=get_posts(array('post_type'=>'aisa_knowledge','post_status'=>'private','posts_per_page'=>100,'meta_key'=>'aisa_conversation_id','meta_value'=>(int)$post->ID,'suppress_filters'=>true));if(count($remaining)>=100)return false;foreach($remaining as$draft)if(!AISA_Agent::knowledge_approved($draft))return false;
  return (bool)wp_delete_post($post->ID,true)&&get_post($post->ID)===null;
 }
 private static function prune(){foreach(self::posts()as$p){$s=self::state($p);if($s&&$s['expires']<=time()&&!self::purge($p))return false;}return true;}
 public static function cleanup(){if(!add_option(self::LOCK,time(),'','no'))return;try{self::prune();}finally{delete_option(self::LOCK);}if(self::posts()&&!wp_next_scheduled(self::CLEAN))wp_schedule_single_event(time()+HOUR_IN_SECONDS,self::CLEAN);}
 public static function delete_user($uid){if(!self::posts(array('author'=>(int)$uid)))return;if(!add_option(self::LOCK,time(),'','no'))wp_die('Support records are busy. Retry account deletion.','',array('response'=>409));try{foreach(self::posts(array('author'=>(int)$uid))as$p)if(!self::purge($p))wp_die('Support data cleanup failed. Account deletion stopped.','',array('response'=>503));}finally{delete_option(self::LOCK);}}
 public static function export_personal($email,$page=1){$out=array();$u=is_string($email)?get_user_by('email',$email):false;if(!current_user_can('manage_options')||!$u||$page!==1)return array('data'=>array(),'done'=>true);foreach(self::posts(array('author'=>(int)$u->ID))as$p){$s=self::state($p);if(!$s||$s['expires']<=time())continue;$text=array();foreach($s['messages']as$m)$text[]='Customer: '.$m['question']."\n".($m['outcome']==='human'?'Support agent: ':'AI assistant: ').$m['answer'];$out[]=array('group_id'=>'aisa-conversations','group_label'=>'AI support conversations','item_id'=>'aisa-chat-'.$p->ID,'data'=>array(array('name'=>'Conversation','value'=>implode("\n\n",$text))));}return array('data'=>$out,'done'=>true);}
 public static function erase_personal($email,$page=1){$removed=false;$retained=false;$u=is_string($email)?get_user_by('email',$email):false;if(!current_user_can('manage_options')||!$u||$page!==1)return array('items_removed'=>false,'items_retained'=>false,'messages'=>array(),'done'=>true);if(!add_option(self::LOCK,time(),'','no'))return array('items_removed'=>false,'items_retained'=>true,'messages'=>array('Support records are busy; retry.'),'done'=>true);try{foreach(self::posts(array('author'=>(int)$u->ID))as$p){if(self::purge($p))$removed=true;else$retained=true;}}finally{delete_option(self::LOCK);}return array('items_removed'=>$removed,'items_retained'=>$retained,'messages'=>$retained?array('Some support records could not be removed. Retry cleanup.'):array(),'done'=>true);}
 public static function records($trash=false){if(!current_user_can('manage_options'))return array();$out=array();foreach(self::posts(array('post_status'=>$trash?'trash':'private','order'=>'DESC'))as$p){$s=self::state($p);if($s&&$s['expires']>time())$out[]=array('id'=>(int)$p->ID,'state'=>$s);}return $out;}
 public static function form($operation,$extra=array()){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('aisa_conversation');echo '<input type="hidden" name="action" value="aisa_conversation"><input type="hidden" name="operation" value="'.esc_attr($operation).'">';foreach(AISA_Live_Inbox::navigation($_GET)as$k=>$v)if($v!==null)echo '<input type="hidden" name="ui_'.esc_attr($k).'" value="'.esc_attr($v).'">';foreach($extra as$k=>$v)echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';}
 public static function audit($event){wp_insert_post(array('post_type'=>'aisa_audit','post_status'=>'private','post_title'=>'Conversation '.$event,'post_content'=>wp_json_encode(array('site'=>get_current_blog_id(),'actor'=>get_current_user_id()))));foreach(get_posts(array('post_type'=>'aisa_audit','post_status'=>'private','posts_per_page'=>100,'offset'=>100,'fields'=>'ids','orderby'=>'ID','order'=>'DESC'))as$id)wp_delete_post($id,true);}
 public static function handle(){
  self::guard();$op=is_string($_POST['operation']??null)?$_POST['operation']:'';
  if($op==='configure'){$old=self::config();$revision=wp_unslash($_POST['config_revision']??'');if(!is_string($revision)||!hash_equals(self::config_revision(),$revision))wp_die('Configuration changed. Reload first.','',array('response'=>409));$next=array('enabled'=>empty($_POST['enabled'])?0:1,'auto_review'=>empty($_POST['auto_review'])?0:1,'actor'=>get_current_user_id());if(!$next['enabled'])$next['auto_review']=0;update_option(self::CONFIG,$next,false);if(self::config()!==$next)wp_die('Configuration could not be verified.','',array('response'=>503));AISA_Admin_Assistant::schedule();self::audit('configuration updated');}
  elseif(in_array($op,array('takeover','resume','resolve','human_reply','mark_read','organize'),true)){$result=AISA_Live_Inbox::staff($op,absint($_POST['id']??0),$_POST['revision']??'',array('message'=>wp_unslash($_POST['message']??''),'request_id'=>wp_unslash($_POST['request_id']??''),'topic'=>wp_unslash($_POST['topic']??''),'priority'=>wp_unslash($_POST['priority']??'')));if(is_wp_error($result))wp_die(esc_html($result->get_error_message()),'',array('response'=>$result->get_error_data()['status']??400));}
  elseif(in_array($op,array('delete','restore'),true)){$p=get_post(absint($_POST['id']??0));$s=self::state($p);if(!$s||$s['expires']<=time())wp_die('Chat not found.','',array('response'=>404));if((string)$s['revision']!==(string)($_POST['revision']??''))wp_die('Chat changed. Reload first.','',array('response'=>409));if(!add_option(self::LOCK,time(),'','no'))wp_die('Inbox busy. Retry.','',array('response'=>409));try{if($op==='restore'){if(is_wp_error(AISA_Live_Inbox::invalidate($p->ID)))wp_die('Chat control could not be verified.','',array('response'=>503));}$result=$op==='delete'?wp_trash_post($p->ID):wp_untrash_post($p->ID);if($result&&$op==='delete'&&is_wp_error(AISA_Live_Inbox::invalidate($p->ID)))wp_die('Chat removed; refresh before restoring.','',array('response'=>503));if(!$result)wp_die('Chat action failed.','',array('response'=>503));if($op==='restore'&&get_post_status($p->ID)!=='private'){wp_update_post(array('ID'=>$p->ID,'post_status'=>'private'));}if(get_post_status($p->ID)!==($op==='delete'?'trash':'private'))wp_die('Chat action could not be verified.','',array('response'=>503));self::audit($op==='delete'?'deleted':'restored');}finally{delete_option(self::LOCK);}}
  else{AISA_Admin_Assistant::handle($op);return;}
  $ui=array();foreach(array('chat_page','chat_filter','chat_search','chat_trash')as$k)$ui[$k]=$_POST['ui_'.$k]??null;$ui=AISA_Live_Inbox::navigation($ui);$ui['chat_id']=absint($_POST['id']??0)?:null;wp_safe_redirect(add_query_arg(array_merge(array('page'=>'aisa','view'=>$op==='configure'?'settings':'inbox'),$ui),admin_url('admin.php')));exit;
 }
 public static function render_settings(){
  if(!current_user_can('manage_options'))return;$c=self::config();echo '<section class="aisa-section"><div class="aisa-section-heading"><div><h2>Chat settings</h2><p>Choose whether future website conversations may be saved.</p></div></div><details class="aisa-card"><summary>Chat saving options</summary><h3>Conversation capture</h3>';self::form('configure',array('config_revision'=>self::config_revision()));echo '<label><input type="checkbox" name="enabled" value="1" '.checked($c['enabled'],1,false).'> Enable future consented support chats</label><p class="aisa-help">Off by default. The customer chooses whether to save a support chat. Detected credentials, personal details and private links are omitted; automated masking cannot guarantee removal of every personal detail. Commerce tool results are never captured.</p><label><input type="checkbox" name="auto_review" value="1" '.checked($c['auto_review'],1,false).'> Automatically suggest Training drafts from new conversations</label><p class="aisa-help">Uses the configured provider only after this deliberate activation. Check provider terms and privacy notice before real customer use. Drafts stay unapproved; customer messages never authorize settings changes or tool actions. Scheduled work is bounded and timing depends on WordPress cron.</p><button class="button button-primary">Save inbox options</button></form></details>';
  echo '</section>';
 }
 public static function render(){
  if(!current_user_can('manage_options'))return;$trash=isset($_GET['chat_trash']);echo '<section class="aisa-section aisa-inbox-only"><h2 class="aisa-screen-reader">Chat Inbox</h2><p class="aisa-chat-folder"><a href="'.esc_url(add_query_arg(array('page'=>'aisa','view'=>'inbox','chat_trash'=>$trash?null:1),admin_url('admin.php'))).'">'.($trash?'Back to inbox':'Deleted chats').'</a></p>';AISA_Live_Inbox::render($trash);echo '</section>';
 }
}

